// Node 3: Calculate Remaining Days, Filter Expiring (3d & 0d), Check Consent & Same-Day Idempotency
const formatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});
const todayIST = formatter.format(new Date());
const [y1, m1, d1] = todayIST.split('-').map(Number);
const utcToday = Date.UTC(y1, m1 - 1, d1);

const qualifyingMembers = [];

for (const item of $input.all()) {
  const member = item.json;
  if (!member.Expiry_Date || !/^\d{4}-\d{2}-\d{2}$/.test(member.Expiry_Date)) continue;

  // 1. Check WhatsApp Consent
  if (String(member.WhatsApp_Consent).toUpperCase() !== 'TRUE') continue;

  // 2. Prevent duplicate reminder on the same day
  if (String(member.Last_Reminder_Date) === todayIST) continue;

  // 3. Calculate Remaining Days
  const [y2, m2, d2] = member.Expiry_Date.split('-').map(Number);
  const utcExpiry = Date.UTC(y2, m2 - 1, d2);
  const daysRemaining = Math.round((utcExpiry - utcToday) / (1000 * 60 * 60 * 24));

  if (daysRemaining === 3 || daysRemaining === 0) {
    const reminderType = daysRemaining === 3 ? '3DAY_EXPIRY' : 'TODAY_EXPIRY';
    const templateName = daysRemaining === 3 ? 'gym_expiry_3day_reminder' : 'gym_expiry_today_reminder';
    const messagePreview = daysRemaining === 3
      ? `Hello ${member.Name}, your gym membership expires in 3 days. Please renew your membership to continue enjoying our facilities. Thank you!`
      : `Hello ${member.Name}, your gym membership expires today. Please renew your plan to continue your fitness journey!`;

    qualifyingMembers.push({
      json: {
        ...member,
        Today_IST: todayIST,
        Days_Remaining: daysRemaining,
        Reminder_Type: reminderType,
        Template_Name: templateName,
        Message_Preview: messagePreview,
        Reminder_ID: `REM-${Date.now()}-${member.Member_ID}`
      }
    });
  }
}

return qualifyingMembers;
